mapper.update:
update ontology_analysis_run set status = #{status}, stage = #{stage}, model_calls = #{modelCalls},
    finished_at = #{finishedAt}, proposal_id = #{proposalId}
where task_id = #{taskId} and run_token = #{runToken} and status = 'RUNNING'

mapper.select:
select r.run_id, r.run_kind, r.source_id, r.wiki_space_id, r.selection_json, r.username, r.started_at,
    case when j.lease_until <= #{now} then j.lease_until else r.finished_at end as finished_at,
    case when j.lease_until <= #{now} then 'INTERRUPTED' else r.status end as status,
    coalesce(j.stage, r.stage) as stage, coalesce(j.model_calls, r.model_calls) as model_calls, r.proposal_id
from ontology_analysis_run r
join analysis_task t on t.task_id = r.task_id
left join ontology_analysis_job j on j.task_id = r.task_id and j.run_token = r.run_token and r.status = 'RUNNING'
where r.task_id = #{taskId}
and r.run_id < #{before}
order by r.run_id desc limit #{limit}

mapper.update:
update ontology_analysis_job set stage = #{stage}, checkpoint_json = #{checkpointJson}, message = #{message},
    lease_until = #{leaseUntil}, model_calls = #{modelCalls}, updated_at = current_timestamp
where task_id = #{taskId} and run_token = #{runToken} and status = 'RUNNING' and lease_until > #{now}
